<?php
declare(strict_types=1);namespace App\Http\Requests\Finance;use Illuminate\Foundation\Http\FormRequest;class InvoiceRequest extends FormRequest{public function authorize():bool{return $this->user()?->can($this->isMethod('post')?'finance.invoice.create':'finance.invoice.update')??false;}public function rules():array{return ['student_id'=>'required|exists:students,id','academic_year_id'=>'required|exists:academic_years,id','semester_id'=>'nullable|exists:semesters,id','fee_type_id'=>'required|exists:fee_types,id','billing_month'=>'required|date_format:Y-m','issue_date'=>'required|date','due_date'=>'required|date|after_or_equal:issue_date','amount'=>'required|integer|min:1|max:999999999999','description'=>'nullable|string|max:255'];}}
